let show=true;

return(

<div
style={{
display:"flex",
justifyContent:"space-around"
}}
>

{

show ?

<>

<CourseDetails/>

<BookDetails/>

<BlogDetails/>

</>

:

<h1>No Data Available</h1>

}

</div>

);

}

export default App;
